insert into public.listings(id,title,city,category,summary,address,source_url,checked_at,origin,publication_status,out_of_city,verified_fields) values('00000000-0000-4000-8000-000000000107','Пещера Коныр-Аулие','semey','Природа','Коныр-Аулие (Қоңыр әулие) — пещера с подземным озером в горах Актас, Абайский район области Абай. Загородное направление рядом с селом Токтамыс. Перед поездкой уточните доступность спуска, состояние дороги, транспорт и условия посещения.','Область Абай, Абайский район, гора Актас, окрестности села Токтамыс','https://visitabay.kz/abai-zholy/82-konyr-aulie.html','2026-10-20T11:00:00Z','real_verified','published',true,array['title','category','summary','address']) on conflict(id) do update set out_of_city=excluded.out_of_city,verified_fields=excluded.verified_fields;
